-- Name: check_signup_email(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_signup_email(p_email text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_profile_created boolean;
BEGIN
  SELECT profile_created INTO v_profile_created
  FROM public.signup_tracker
  WHERE email = p_email;

  IF NOT FOUND THEN
    RETURN 'signup';
  END IF;

  IF v_profile_created THEN
    RETURN 'exists';
  END IF;

  DELETE FROM public.signup_tracker
  WHERE email = p_email AND NOT profile_created;

  RETURN 'signup';
END;
$$;


--

-- Name: upsert_signup_tracker(text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_signup_tracker(p_email text, p_profile_created boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF p_profile_created
     AND auth.jwt() ->> 'email' IS DISTINCT FROM p_email THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = 'P0001';
  END IF;
  INSERT INTO public.signup_tracker (email, profile_created, created_at, updated_at)
  VALUES (p_email, p_profile_created, now(), now())
  ON CONFLICT (email) DO UPDATE
    SET profile_created = EXCLUDED.profile_created,
        updated_at = now();
END;
$$;


